-- Academy: rebuild Yachts Module 1 as "Welcome to Yachting" (10 pages with quick checks + 7-question final quiz)
-- and make the pass mark 60% of the questions in a module (3/5 stays 3/5, 5/7 for this module).
-- Run this once in the Supabase SQL editor. Existing pass/fail progress for the module is kept;
-- learners' old quick-check answers for this module are cleared with the old pages.

do $mig$
declare
  v_module uuid;
  v_q uuid;
  rec jsonb;
  n int := 0;
  i int;
  v_pages jsonb := $json$[{"heading": "Welcome to Yachting: What Is This World?", "body": "<p><b>Before we begin</b></p><p>You are about to enter an industry that, from the outside, can look almost impossibly glamorous.</p><p>A yacht in Monaco.<br/>A helicopter on the foredeck.<br/>A glass of champagne at anchor.<br/>A beautiful yacht leaving port at sunset.</p><p>And sometimes, a price tag of €8 million, €25 million or €80 million.</p><p>You may wonder:</p><p><em>What does it actually take to sell one of these?</em></p><p>That is where this academy begins.</p><p>Not with sales techniques.<br/>Not with contracts.<br/>Not with memorising specifications.</p><p>We begin by understanding the world itself.</p><p>Because yacht brokerage is not simply <b>selling boats</b>.</p><p>It sits at the intersection of luxury, finance, sales, hospitality, marine knowledge, international business, negotiation and relationships.</p><p><b>At the centre of all of it is one thing: trust</b></p><p>A client is making a major financial decision.<br/>A seller is entrusting you with a valuable asset.<br/>Other professionals are relying on you to communicate accurately and behave professionally.<br/>Your reputation travels with every interaction.</p><p>That is why this academy will not try to turn you into someone who simply knows yachts.</p><p>It will teach you to understand the market, read people, recognise opportunities, communicate professionally and make sound recommendations.</p><p>Most importantly, it will help you decide whether this world is right for you.</p><p>By the end of this module, you should be able to answer one question with greater confidence:</p><p><em>Could I genuinely see myself building a career here?</em></p><p>Let's begin.</p>", "q": "According to this page, what sits at the centre of yacht brokerage?", "opts": ["Deep technical knowledge of engines", "Sales techniques", "Trust", "The size of the yacht being sold"], "correct": 2}, {"heading": "Chapter 1: Your Introduction to the Yacht World", "body": "<p><b>The first thing to understand</b></p><p>If you are completely new to yachting, the word \"yacht\" covers an enormous range of vessels, businesses and lifestyles.</p><p>A yacht might be a 10-metre motorboat used for weekends.<br/>It might be a 30-metre sailing yacht cruising the Mediterranean.<br/>It might be a 60-metre motor yacht with a professional crew.<br/>It might be a 100-metre-plus superyacht with dozens of crew, sophisticated engineering, multiple tenders and an enormous annual operating budget.</p><p>They are all yachts.</p><p>Professionally, however, they can represent very different businesses.</p><p>A beginner often sees:</p><p><b>size + bedrooms + speed + price.</b></p><p>A broker learns to look for:</p><p><b>purpose + condition + ownership + market position + operating reality + desirability + risk.</b></p><p>That change in perspective is one of the first transformations you will make.</p><p><b>The first mental model</b></p><p>Whenever you look at a yacht, train yourself to ask five questions:</p><p><b>1. What is it?</b><br/>What type of yacht is it?</p><p><b>2. What was it designed to do?</b><br/>Cruise the Mediterranean? Cross oceans? Enter shallow anchorages? Entertain large groups? Explore remote destinations?</p><p><b>3. Who is it for?</b><br/>A family? A couple? An experienced owner? A first-time buyer? A charter client?</p><p><b>4. What does it cost to own and operate?</b><br/>The purchase price is only the beginning.</p><p><b>5. Why would someone choose this yacht over another?</b><br/>That final question is the beginning of broker thinking.</p><p><b>Broker's insight</b></p><p><em>The yacht is the product. The client is the reason for the recommendation.</em></p><p>A beautiful yacht can still be completely wrong for a particular client.</p><p>Your job is not to fall in love with the yacht.</p><p>Your job is to understand why someone else might.</p>", "q": "Which best describes how a broker's view of a yacht differs from a beginner's?", "opts": ["A broker focuses more on the number of cabins", "A broker looks beyond size and price to purpose, condition, ownership, market position, operating reality and risk", "A broker memorises every specification before forming a view", "A broker falls in love with the yacht so they can sell it with passion"], "correct": 1}, {"heading": "Chapter 2: The World Behind the Yacht", "body": "<p><b>The yacht you see is only the surface</b></p><p>Walk through a marina and you may see a row of spectacular yachts.</p><p>To the casual observer, the yacht is the product.</p><p>To the industry, it is the centre of an ecosystem.</p><p>Behind a serious yacht there may be:</p><p>&bull; designers<br/>&bull; shipyards<br/>&bull; captains<br/>&bull; engineers<br/>&bull; crew<br/>&bull; management companies<br/>&bull; surveyors<br/>&bull; insurers<br/>&bull; lawyers<br/>&bull; financiers<br/>&bull; accountants<br/>&bull; registration specialists<br/>&bull; brokers<br/>&bull; suppliers<br/>&bull; charter professionals<br/>&bull; and many other specialists.</p><p>The broker operates within this network. Understanding that network is essential.</p><p><b>Know what you know</b></p><p>Suppose a client asks:</p><p><em>\"The captain says the engine maintenance is due in six months. Is that a problem?\"</em></p><p>A professional broker should not guess. Nor should they pretend to be an engineer.</p><p>The broker recognises that the question is technical and knows where to obtain the appropriate professional opinion.</p><p>This principle will become increasingly important throughout the academy:</p><p><em>Know enough to recognise the issue. Know when to involve the expert.</em></p><p>You don't need to be the best engineer on the dock. You need to know when an engineer should be involved.</p><p><b>The business behind the asset</b></p><p>Imagine a €20 million yacht. The transaction may involve a buyer, a seller, brokers, lawyers, a surveyor, a captain, a management company, a shipyard, insurance professionals, a lender and technical specialists.</p><p>Not every transaction will involve all of them. But the principle remains: <b>yacht brokerage is an ecosystem business.</b> A broker creates value partly by helping the client navigate that ecosystem.</p><p><b>Reality check</b></p><p>The yacht industry has glamorous moments. It also has spreadsheets, contracts, follow-up, travel delays, disappointed clients, failed negotiations, technical problems, paperwork, compliance and uncertainty.</p><p>The glamorous moments are real. They simply aren't the whole profession.</p><p>Ask yourself:</p><p><em>Would I still be interested if much of my working week involved communication, research, administration and follow-up?</em></p><p>That answer matters.</p>", "q": "A client asks whether upcoming engine maintenance is a problem. What should a professional broker do?", "opts": ["Give a confident answer to keep the client's trust", "Tell the client technical matters don't affect the deal", "Wait until the survey and hope it isn't mentioned", "Recognise it is a technical issue and involve the appropriate specialist"], "correct": 3}, {"heading": "Chapter 3: The Yacht Industry Map", "body": "<p><b>Where do you fit?</b></p><p>Yacht brokerage is one part of the wider industry.</p><p>You may begin this academy thinking:</p><p><em>\"I want to become a yacht broker.\"</em></p><p>And discover that another area interests you more.</p><p>That is not failure. That is useful information.</p><p><b>The major areas of the industry</b></p><p><b>1. Yacht Brokerage</b><br/>Brokers help clients buy, sell and, depending on their specialisation, charter yachts. Their work can include prospecting, listings, market research, yacht selection, viewings, negotiation, transaction coordination and communication.</p><p><b>2. Yacht Management</b><br/>Management companies may oversee technical operations, financial administration, crew, compliance, maintenance and procurement.</p><p><b>3. Charter</b><br/>Charter professionals match clients with yachts and coordinate the experience around yacht selection, itineraries, contracts, preferences, destinations and logistics.</p><p><b>4. Shipyards</b><br/>Shipyards build, refit and repair yachts.</p><p><b>5. Design &amp; Naval Architecture</b><br/>Designers shape the appearance, layout and experience of a yacht. Naval architects work with the technical principles behind its design and performance.</p><p><b>6. Crew</b><br/>Captains, engineers, deck crew, interior crew, chefs and other specialists operate the yacht and care for its guests.</p><p><b>7. Survey &amp; Technical Services</b><br/>Surveyors and technical specialists assess condition, systems, construction and other technical matters.</p><p><b>8. Insurance</b><br/>Specialists help owners and operators manage the risks associated with valuable and complex assets.</p><p><b>9. Finance</b><br/>Financing can become part of some yacht acquisitions.</p><p><b>10. Legal &amp; Corporate Services</b><br/>Specialists may advise on contracts, ownership structures, registration, compliance and related matters.</p><p><b>Career discovery exercise</b></p><p>Rate your initial curiosity from 1 to 5 for each area. Keep the scores in your notes.</p><p>&bull; Yacht Brokerage: __ /5<br/>&bull; Charter: __ /5<br/>&bull; Yacht Management: __ /5<br/>&bull; Shipyards: __ /5<br/>&bull; Design: __ /5<br/>&bull; Naval Architecture: __ /5<br/>&bull; Crew / Yacht Operations: __ /5<br/>&bull; Survey / Technical: __ /5<br/>&bull; Finance: __ /5<br/>&bull; Legal / Corporate: __ /5</p><p>Don't treat this as a career test. It is a snapshot. You will revisit it later.</p>", "q": "You realise another area of yachting interests you more than brokerage. What does this chapter say that means?", "opts": ["It is useful information, not a failure", "You should leave the academy", "You should ignore it and choose brokerage anyway", "Brokerage is the only real career in yachting"], "correct": 0}, {"heading": "Chapter 4: The People & the Professions", "body": "<p><b>A yacht is a team</b></p><p>A yacht may look peaceful at anchor. Behind that image can be a highly organised professional operation.</p><p><b>The captain</b><br/>Responsible for the safe operation of the yacht, with significant responsibility for the vessel, crew and guests.</p><p><b>The engineer</b><br/>Responsible for the machinery and technical systems that keep the yacht operating.</p><p><b>The interior team</b><br/>Responsible for guest service and the interior operation.</p><p><b>The deck team</b><br/>Responsible for many exterior and operational functions, including tenders, anchoring, maintenance and water toys.</p><p><b>The chef</b><br/>Responsible for one of the most visible elements of the guest experience: food.</p><p><b>The broker</b><br/>The broker may develop clients, identify yachts, market listings, arrange viewings, advise, negotiate and coordinate the transaction.</p><p>But there is a more useful way to think about the role:</p><p><em>A good broker reduces uncertainty.</em></p><p>A client might see twenty yachts. The broker helps turn twenty possibilities into three serious options. Then three into one.</p><p>That is value.</p><p><b>Brokerage is not simply selling</b></p><p>A salesperson may think:</p><p><em>How do I get this product sold?</em></p><p>A broker should be asking:</p><p><em>What does this client actually need, and which opportunity best fits?</em></p><p>Sometimes the answer will be the yacht they represent. Sometimes it will not.</p><p>That distinction is fundamental to professional credibility.</p>", "q": "According to this chapter, what is one of a good broker's most valuable contributions?", "opts": ["Guaranteeing that the client will buy", "Personally inspecting the machinery", "Reducing uncertainty by turning many possibilities into a few serious options", "Sending as many messages as possible"], "correct": 2}, {"heading": "Chapter 5: A Day in the Life of a Yacht Broker", "body": "<p><b>So what do you actually do all day?</b></p><p>There is no single typical day.</p><p>One day may involve a yacht viewing. Another may involve hours of calls and emails. Another may involve travel. Another may involve negotiating a transaction that ultimately doesn't happen.</p><p>That variety is part of the profession. So is the uncertainty.</p><p><b>A typical working rhythm</b></p><p><b>Morning: market &amp; messages</b><br/>Review new listings, price changes, client requirements, messages from other brokers and ongoing transactions.</p><p><b>Late morning: client work</b><br/>Follow up after viewings. Clarify requirements. Send information. Ask questions. Update clients.</p><p><b>Midday: business development</b><br/>Prospecting. Relationship building. Searching for buyers, sellers, referrals and opportunities.</p><p><b>Afternoon: yachts &amp; transactions</b><br/>A viewing. A call with another broker. A discussion with a captain. Transaction coordination. Research. Negotiation.</p><p><b>End of day: follow-through</b><br/>Confirm appointments. Send documents. Chase outstanding information. Update clients. Prepare for tomorrow.</p><p>The details change. The underlying disciplines do not.</p><p><b>The sales cycle</b></p><p>A yacht transaction may involve:</p><p>1. Initial contact<br/>2. Qualification<br/>3. Yacht selection<br/>4. Viewing<br/>5. Questions<br/>6. Offer<br/>7. Negotiation<br/>8. Agreement<br/>9. Deposit<br/>10. Survey<br/>11. Sea trial<br/>12. Further negotiation<br/>13. Contractual conditions<br/>14. Closing<br/>15. Delivery</p><p>Not every transaction follows exactly this sequence. But the lesson is important:</p><p><b>A broker needs patience.</b></p><p>A transaction can take time. And a transaction can fail after significant work. That is part of the business.</p>", "q": "What does the yacht sales cycle teach a new broker?", "opts": ["Every deal follows the same sequence and always closes", "A deal can take time and can fail after significant work, so patience matters", "Only the offer stage requires real skill", "Most deals close within a few days of the first viewing"], "correct": 1}, {"heading": "Chapter 6: Could Yachting Be for You?", "body": "<p><b>Now we turn the mirror toward you</b></p><p>You don't need to decide today. You need evidence. Over this academy, you will collect it.</p><p><b>The qualities that matter</b></p><p>There is no single broker personality. But certain behaviours tend to matter.</p><p><b>Curiosity</b>: you need to want to keep learning.<br/><b>Observation</b>: clients often reveal priorities through behaviour as well as words.<br/><b>Discipline</b>: follow-up, preparation and consistency matter.<br/><b>Resilience</b>: not every client buys, not every seller chooses you, not every deal closes.<br/><b>Commercial awareness</b>: yachts are assets, clients have budgets, companies need revenue, time matters.<br/><b>Communication</b>: listening, questioning, explaining clearly and managing expectations.<br/><b>Discretion</b>: clients may share highly private information. Professional confidentiality and judgment matter.</p><p><b>The career-change question</b></p><p>Perhaps you already have ten or twenty years of professional experience. Don't assume you are starting from zero. Your previous career may have given you valuable skills.</p><p>&bull; A person from hospitality may understand service and demanding clients.<br/>&bull; Someone from property may understand high-value transactions.<br/>&bull; Someone from finance may understand numbers and risk.<br/>&bull; Someone from luxury retail may understand premium clients.<br/>&bull; Someone from sales may understand prospecting and negotiation.<br/>&bull; Someone from entrepreneurship may understand uncertainty and self-direction.</p><p>Your task is not to erase your previous career. It is to translate it. You will do that properly in Module 9.</p><p><b>The three tests</b></p><p>Before deciding whether brokerage suits you, ask three questions.</p><p><b>1. Do I like the product?</b><br/>You don't need to be obsessed with yachts. But if they leave you completely cold, pay attention.</p><p><b>2. Do I like the people?</b><br/>Brokerage is relationship-heavy.</p><p><b>3. Do I like the process?</b><br/>Do you enjoy researching, comparing, questioning, presenting, negotiating, following up, solving problems, learning and dealing with uncertainty? This is where much of the real job lives.</p>", "q": "How does this chapter suggest you treat your previous career?", "opts": ["Set it aside, because it is irrelevant to yachting", "Keep it out of your profile to look more focused", "Rely on it alone without learning the industry", "Translate its skills into strengths for brokerage"], "correct": 3}, {"heading": "Broker Challenge: Your First Client", "body": "<p><b>Your first client</b></p><p>A new client contacts you:</p><p><em>\"I've never owned a yacht before. I have a budget of €8 million. I want something beautiful for my family, but I don't know what I actually need.\"</em></p><p>They have two children. They spend summers in the Mediterranean. They enjoy entertaining. They don't want an enormous crew. They want to visit smaller ports.</p><p>They also tell you:</p><p><em>\"I want something impressive.\"</em></p><p>You have not met them. You know almost nothing else.</p><p><b>Your task</b></p><p>Write the <b>ten questions</b> you would ask before recommending a yacht. Think about family, lifestyle, destinations, experience, budget, crew, usage, design, entertainment and priorities.</p><p>Then identify: <b>which three questions are most important, and why?</b></p><p>Write your answers in your own notes. You will want them for your portfolio.</p><p><b>Reflection</b></p><p>&bull; Before this module, I thought yacht brokerage was...<br/>&bull; Now I understand that yacht brokerage is...<br/>&bull; The part of the industry that interests me most is...<br/>&bull; The part that interests me least is...<br/>&bull; One thing that surprised me was...<br/>&bull; One thing I want to learn more about is...</p><p>My interest in exploring yacht brokerage is currently: much lower, slightly lower, about the same, slightly higher, or much higher. And why?</p>", "q": "Before recommending any yacht to this first client, what should you do?", "opts": ["Ask questions to understand their needs, lifestyle and priorities", "Send a list of every yacht within €8 million", "Recommend the largest yacht that fits the budget, since they want something impressive", "Wait for the client to decide what they need"], "correct": 0}, {"heading": "Your First Professional Output: My Yacht World Map", "body": "<p><b>My Yacht World Map</b></p><p>Create a one-page document in your own notes containing the following.</p><p><b>The yacht</b></p><p>Three yacht types I have discovered:<br/>1.<br/>2.<br/>3.</p><p>Three features I find interesting:<br/>1.<br/>2.<br/>3.</p><p>Three questions I still have:<br/>1.<br/>2.<br/>3.</p><p><b>The industry</b></p><p>List the major areas of yachting that interest you.</p><p><b>My potential fit</b></p><p>Three strengths I already have:<br/>1.<br/>2.<br/>3.</p><p>Three skills I may need to develop:<br/>1.<br/>2.<br/>3.</p><p><b>My current career hypothesis</b></p><p><em>At this stage, I am curious about yacht brokerage because...</em></p><p><em>The biggest question I still have is...</em></p><p>Keep this document. It becomes the first page of your <b>Broker Portfolio</b>. You will return to it later.</p>", "q": "What is the My Yacht World Map for?", "opts": ["It is a scored test that decides whether you pass the module", "It is an official qualification you can show clients", "It is the first page of your Broker Portfolio, capturing what you have learned, your strengths and your questions", "It is an advertisement to send to brokerages"], "correct": 2}, {"heading": "Final Challenge & What Comes Next", "body": "<p><b>Final broker challenge</b></p><p>Imagine a friend tells you:</p><p><em>\"I'm thinking about becoming a yacht broker. What is the job actually about?\"</em></p><p>You have two minutes. Explain:</p><p>1. What the industry is.<br/>2. What a broker does.<br/>3. Who the broker works with.<br/>4. What makes the job difficult.<br/>5. What makes it interesting.<br/>6. What kind of person might enjoy it.<br/>7. Why someone should explore the industry before deciding.</p><p>No jargon. No clichés. No brochure language.</p><p>Explain it as you would to an intelligent friend who knows nothing about yachting.</p><p>Then read it back. If it sounds like advertising, rewrite it. If it sounds honest, clear and human, keep it.</p><p><b>Final reflection</b></p><p>You have now taken your first step into the yacht world.</p><p>You don't yet know how to value a yacht. You don't know how to structure a deal. You don't know how to negotiate with a seller. You don't know how to read a full specification.</p><p>That's exactly where you should be.</p><p>The first stage of becoming a professional is not pretending to know. It is learning <b>what you need to know</b>.</p><p>Perhaps you are fascinated. Perhaps you're uncertain. Perhaps you love the yachts but aren't convinced about brokerage. Perhaps the commercial side interests you more than the yachts themselves.</p><p>Keep that answer. We are going to test it.</p><p><b>What comes next</b></p><p>You have met the industry. Now it is time to meet the product.</p><p>Because if you are going to advise someone to spend millions on a yacht, you need to understand what you are actually looking at: its design, its purpose, its spaces, its machinery, its numbers, its compromises, its strengths and its weaknesses.</p><p>And ultimately:</p><p><em>Why might this yacht be right for this client, and why might it be wrong?</em></p><p>That is where we go next: <b>Module 2, Meet the Yacht.</b> Do I actually find yachts interesting?</p><p>Welcome aboard.</p>", "q": "What tone does the final challenge ask for when explaining brokerage to a friend?", "opts": ["Brochure language that highlights the glamour", "Honest, clear and human, with no jargon or clichés", "Technical vocabulary to show how much you know", "As short as possible, in one sentence"], "correct": 1}]$json$::jsonb;
  v_final jsonb := $json$[{"q": "What is the most important difference between a yacht and the yacht business?", "opts": ["The yacht is more expensive.", "The yacht is an asset within a much larger professional ecosystem.", "The yacht always has a professional crew.", "The yacht is always privately owned."], "correct": 1}, {"q": "What is one of a broker's most important roles?", "opts": ["Personally perform every technical inspection.", "Repair yacht machinery.", "Help a client navigate choices, information and the transaction.", "Operate the yacht."], "correct": 2}, {"q": "Why are relationships important in yacht brokerage?", "opts": ["Brokers are required to know everyone.", "Relationships can create trust, information, access and opportunities.", "Relationships eliminate competition.", "Relationships guarantee sales."], "correct": 1}, {"q": "What should a broker do when faced with a highly technical question outside their expertise?", "opts": ["Guess confidently.", "Avoid answering.", "Recognise the issue and involve the appropriate specialist.", "Tell the client technical matters don't matter."], "correct": 2}, {"q": "Why is follow-up important?", "opts": ["Because every follow-up creates a sale.", "Because consistent communication is part of professional relationship management.", "Because brokers need to send as many emails as possible.", "Because clients always expect daily contact."], "correct": 1}, {"q": "Is yacht brokerage the only career within yachting?", "opts": ["Yes, it is the only career in the industry.", "No, there are many careers, including management, charter, crew, design and technical roles.", "Yes, all other roles are part of brokerage.", "Only for people with a marine background."], "correct": 1}, {"q": "What should you do if another area of yachting interests you more than brokerage?", "opts": ["Ignore it.", "Leave the academy.", "Explore that interest further.", "Choose brokerage anyway."], "correct": 2}]$json$::jsonb;
begin
  select id into v_module from public.academy_modules where track = 'yachts' and module_number = 1;
  if v_module is null then
    raise exception 'Yachts module 1 not found';
  end if;

  update public.academy_modules
     set title = 'Welcome to Yachting', description = 'What is this world?'
   where id = v_module;

  -- pages first (their checkpoint responses cascade), then every question for the module (options cascade)
  delete from public.academy_module_pages where module_id = v_module;
  delete from public.academy_quiz_questions where module_id = v_module;

  for rec in select * from jsonb_array_elements(v_pages) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage, page_number)
    values (v_module, rec->>'q', 0, 'checkpoint', n)
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;

    insert into public.academy_module_pages (module_id, page_number, heading, body_html, checkpoint_question_id)
    values (v_module, n, rec->>'heading', rec->>'body', v_q);
  end loop;

  n := 0;
  for rec in select * from jsonb_array_elements(v_final) loop
    n := n + 1;
    insert into public.academy_quiz_questions (module_id, question_text, order_index, stage)
    values (v_module, rec->>'q', n - 1, 'final')
    returning id into v_q;

    for i in 0 .. jsonb_array_length(rec->'opts') - 1 loop
      insert into public.academy_quiz_options (question_id, option_text, is_correct, order_index)
      values (v_q, rec->'opts'->>i, i = (rec->>'correct')::int, i);
    end loop;
  end loop;
end
$mig$;

-- Pass mark = 60% of the module's final questions (rounded up). Same gate as before: every quick check must be answered first.
create or replace function public.submit_module_quiz(p_module_id uuid, p_answers jsonb)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_user uuid := auth.uid();
  v_score int := 0;
  v_total int := 0;
  v_passed boolean;
  v_attempts int;
  v_prev_passed boolean;
  v_correct_map jsonb := '{}'::jsonb;
  v_missing int;
  q record;
  v_correct_option uuid;
  v_submitted_option uuid;
begin
  if v_user is null then
    raise exception 'Not authenticated';
  end if;

  if not public.is_admin() then
    select count(*) into v_missing
    from public.academy_module_pages pg
    where pg.module_id = p_module_id
      and pg.checkpoint_question_id is not null
      and not exists (
        select 1 from public.academy_checkpoint_responses r
        where r.user_id = v_user and r.page_id = pg.id
      );
    if v_missing > 0 then
      raise exception 'Complete all pages and quick checks before taking the quiz';
    end if;
  end if;

  for q in
    select id from public.academy_quiz_questions
    where module_id = p_module_id and stage = 'final'
  loop
    v_total := v_total + 1;
    select id into v_correct_option
    from public.academy_quiz_options
    where question_id = q.id and is_correct = true
    limit 1;

    v_correct_map := v_correct_map || jsonb_build_object(q.id::text, v_correct_option);

    v_submitted_option := nullif(p_answers ->> q.id::text, '')::uuid;
    if v_submitted_option is not null and v_submitted_option = v_correct_option then
      v_score := v_score + 1;
    end if;
  end loop;

  v_passed := v_total > 0 and v_score >= ceil(v_total * 0.6);

  select quiz_passed, attempts into v_prev_passed, v_attempts
  from public.user_module_progress
  where user_id = v_user and module_id = p_module_id;

  v_attempts := coalesce(v_attempts, 0) + 1;

  insert into public.user_module_progress
    (user_id, module_id, video_watched, quiz_passed, quiz_score, attempts, completed_at)
  values
    (v_user, p_module_id, true, v_passed or coalesce(v_prev_passed, false), v_score, v_attempts,
     case when v_passed then now() else null end)
  on conflict (user_id, module_id) do update set
    video_watched = true,
    quiz_passed = excluded.quiz_passed or public.user_module_progress.quiz_passed,
    quiz_score = excluded.quiz_score,
    attempts = excluded.attempts,
    completed_at = case
      when excluded.quiz_passed or public.user_module_progress.quiz_passed
        then coalesce(public.user_module_progress.completed_at, excluded.completed_at)
      else public.user_module_progress.completed_at
    end;

  return jsonb_build_object(
    'score', v_score,
    'total', v_total,
    'passed', v_passed,
    'correctOptions', v_correct_map
  );
end;
$function$;
